"use client";
import React, { useState } from "react";
import { Search, SendHorizontal, Mail, ChevronRight, MessageSquare } from "lucide-react";
import { faqData } from "@/data/faq"; 

export default function FAQPage() {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [filter, setFilter] = useState<string>("All");
  const [searchQuery, setSearchQuery] = useState("");

  const filteredFaqs = faqData.filter((item) => {
    const matchesFilter = filter === "All" || item.category === filter;
    const matchesSearch = item.question.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const categories = ["All", "Shipping", "Orders", "Returns", "Sizing", "Partnerships"];

  const handleGmailRedirect = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const question = formData.get("question") as string;
    
    const recipient = "support@fashionfriday.in";
    // Uses the current filter to give the support team context automatically
    const subject = encodeURIComponent(`Fashion Friday Inquiry: ${filter}`);
    const body = encodeURIComponent(
      `USER QUESTION:\n${question}\n\n---\nCategory: ${filter}\nSource: Web FAQ Dispatch`
    );

    window.location.href = `mailto:${recipient}?subject=${subject}&body=${body}`;
  };

  return (
    <div className="bg-background text-foreground min-h-screen pb-32 transition-colors duration-500">
      
      {/* 1. EDITORIAL HEADER */}
      <section className="pt-32 pb-16 px-6">
        <div className="max-w-7xl mx-auto space-y-12">
          <div className="space-y-4">
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-brand border-l-2 border-brand pl-4">
              Knowledge Base / 2026
            </span>
            <h1 className="text-6xl md:text-8xl font-black uppercase tracking-tighter italic leading-none">
              How can we <br /> <span className="text-foreground-subtle">assist?</span>
            </h1>
          </div>

          <div className="flex flex-col md:flex-row gap-6 items-center">
            <div className="relative flex-1 group w-full">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 opacity-30 group-focus-within:text-brand transition-colors" size={18} />
              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="SEARCH FOR A TOPIC..." 
                className="w-full bg-background-muted rounded-full py-6 pl-14 pr-6 border border-border focus:border-brand outline-none uppercase font-black tracking-widest text-[11px] transition-all"
              />
            </div>
            <div className="flex flex-wrap gap-2 justify-center">
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => setFilter(cat)}
                  className={`px-6 py-4 rounded-full text-[9px] font-black uppercase tracking-widest border transition-all ${
                    filter === cat ? "bg-brand text-brand-foreground border-brand" : "bg-transparent border-border hover:border-brand"
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* 2. DYNAMIC FAQ LIST */}
      <section className="max-w-4xl mx-auto px-6 mb-24">
        {filteredFaqs.length > 0 ? (
          <div className="space-y-4">
            {filteredFaqs.map((faq) => (
              <div 
                key={faq.id}
                className={`rounded-[2.5rem] border transition-all duration-500 overflow-hidden ${
                  activeId === faq.id ? "bg-background-muted border-brand" : "bg-background border-border"
                }`}
              >
                <button 
                  onClick={() => setActiveId(activeId === faq.id ? null : faq.id)}
                  className="w-full px-8 py-8 flex items-center justify-between text-left group"
                >
                   <h3 className="text-lg font-black uppercase tracking-tight italic group-hover:translate-x-2 transition-transform">
                    {faq.question}
                  </h3>
                  <div className={`p-2 rounded-full border border-border transition-all ${activeId === faq.id ? "rotate-90 bg-brand text-brand-foreground" : ""}`}>
                    <ChevronRight size={18} />
                  </div>
                </button>
                {activeId === faq.id && (
                  <div className="px-8 pb-10">
                    <p className="text-foreground-muted leading-relaxed font-medium italic border-t border-border pt-6">
                      {faq.answer}
                    </p>
                  </div>
                )}
              </div>
            ))}
          </div>
        ) : (
          <div className="py-20 text-center space-y-4 opacity-40">
            <MessageSquare className="mx-auto" size={40} />
            <p className="uppercase font-black tracking-widest text-xs italic">No matching archives found.</p>
          </div>
        )}
      </section>

      {/* 3. MINIMALIST DISPATCH NODE (Question Only) */}
      <section className="max-w-7xl mx-auto px-6">
        <div className="rounded-[4rem] p relative overflow-hidden">
          <div className="max-w-3xl mx-auto text-center space-y-12">
            
            <div className="space-y-6">
              <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-background border border-border mx-auto">
                <Mail className="text-brand" size={14} />
                <span className="text-[9px] font-black uppercase tracking-widest">Support Node</span>
              </div>
              <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter italic leading-none">
                Still Need <span className="text-foreground-subtle">Answers?</span>
              </h2>
              <p className="text-foreground-muted text-sm font-medium italic mx-auto max-w-sm">
                If the archive didn't cover your concern, type your question below. We'll bridge you directly to our Gmail dispatch.
              </p>
            </div>

            <div className="bg-background rounded-[3rem] p-4 border-2 border-border relative">
              <form onSubmit={handleGmailRedirect} className="relative">
                <textarea 
                  required
                  name="question"
                  rows={3}
                  placeholder="WRITE YOUR QUESTION HERE..." 
                  className="w-full bg-transparent rounded-[2.5rem] py-8 px-10 outline-none uppercase font-black tracking-widest text-[12px] resize-none transition-all placeholder:opacity-30"
                />
                
                <div className="flex flex-col gap-4 sm:flex-row items-center justify-between px-6 pb-4">
                  <span className="text-[9px] font-black uppercase tracking-widest opacity-30 italic">
                    Sending to: support@fashionfriday.in
                  </span>
                  <button 
                    type="submit"
                    className="bg-brand text-brand-foreground px-8 py-4 rounded-full font-black uppercase tracking-[0.2em] text-[10px] hover:scale-105 active:scale-95 transition-all flex items-center justify-center gap-3 shadow-xl"
                  >
                    Send on Gmail <SendHorizontal size={14} />
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </section>

      <footer className="mt-32 text-center opacity-20">
        <p className="text-[10px] font-black uppercase tracking-[1em] italic">FF Support Grid / 2026</p>
      </footer>
    </div>
  );
}